The current implementation only supports Korean keyword detection for edit intents. This task will enhance it to support both Korean and English with semantic pattern recognition:

1. Expand Korean keyword dictionary (add 20+ patterns)
2. Add English keyword support
3. Implement pattern-based intent classification
4. Add confidence scoring for intent detection
5. Support context-aware intent (follow-up edits)

Implementation approach:
- Create a new IntentDetector class in cli/core/
- Define pattern dictionaries for both languages
- Implement regex and semantic matching

```python
class IntentDetector:
    def __init__(self):
        # Korean patterns
        self.ko_patterns = {
            'add': [r'추가', r'삽입', r'넣어', r'더해'],
            'remove': [r'제거', r'삭제', r'지워', r'없애'],
            'modify': [r'수정', r'변경', r'바꿔', r'고쳐'],
            # Add 20+ more patterns
        }

        # English patterns
        self.en_patterns = {
            'add': [r'add', r'insert', r'include', r'append'],
            'remove': [r'remove', r'delete', r'eliminate', r'take out'],
            'modify': [r'change', r'modify', r'update', r'alter'],
            # Add corresponding English patterns
        }

        # Context patterns for follow-up edits
        self.context_patterns = {
            'continue': [r'also', r'additionally', r'then', r'next', r'그리고', r'또한', r'다음에'],
            'undo': [r'revert', r'undo', r'go back', r'취소', r'되돌려'],
        }

    def detect_intent(self, text, previous_intent=None):
        """Detect edit intent from text with confidence score"""
        # Check for context-aware patterns first
        if previous_intent and any(re.search(p, text, re.IGNORECASE) for patterns in self.context_patterns.values() for p in patterns):
            # This is a follow-up edit
            for intent_type, patterns in self.context_patterns.items():
                if any(re.search(p, text, re.IGNORECASE) for p in patterns):
                    return {
                        'type': intent_type,
                        'base_intent': previous_intent['type'],
                        'confidence': 0.9,  # High confidence for context matches
                        'is_followup': True
                    }

        # Check Korean patterns
        ko_intent = self._check_patterns(text, self.ko_patterns)

        # Check English patterns
        en_intent = self._check_patterns(text, self.en_patterns)

        # Return the intent with higher confidence
        if ko_intent['confidence'] > en_intent['confidence']:
            return ko_intent
        else:
            return en_intent

    def _check_patterns(self, text, pattern_dict):
        best_match = {'type': 'unknown', 'confidence': 0.0}

        for intent_type, patterns in pattern_dict.items():
            # Count how many patterns match
            matches = sum(1 for p in patterns if re.search(p, text, re.IGNORECASE))
            if matches > 0:
                confidence = min(0.5 + (matches * 0.1), 0.9)  # More matches = higher confidence
                if confidence > best_match['confidence']:
                    best_match = {'type': intent_type, 'confidence': confidence, 'is_followup': False}

        return best_match
```

