This task involves creating a centralized configuration system:

1. Create config.py with all settings
2. Support .env file for API keys
3. Add swmate.yaml for project-specific config
4. Implement config validation on startup

Implementation approach:
- Create a ConfigManager class in cli/core/config.py
- Support multiple configuration sources with priority
- Add validation for required settings

```python
import os
import yaml
import json
from typing import Dict, Any, Optional, List, Union
from dataclasses import dataclass, field
from dotenv import load_dotenv

@dataclass
class ConfigValidationError:
    """Configuration validation error"""
    key: str
    message: str

@dataclass
class ConfigSchema:
    """Schema for configuration validation"""
    required: List[str] = field(default_factory=list)
    types: Dict[str, type] = field(default_factory=dict)
    defaults: Dict[str, Any] = field(default_factory=dict)

class ConfigManager:
    """Centralized configuration management"""

    DEFAULT_SCHEMA = ConfigSchema(
        required=['openai_api_key'],
        types={
            'openai_api_key': str,
            'default_model': str,
            'max_tokens': int,
            'temperature': float,
            'log_level': str,
            'cache_ttl': int,
            'session_auto_save': bool,
        },
        defaults={
            'default_model': 'gpt-4',
            'max_tokens': 4000,
            'temperature': 0.7,
            'log_level': 'INFO',
            'cache_ttl': 3600,
            'session_auto_save': True,
        }
    )

    def __init__(self):
        """Initialize configuration manager"""
        self.config = {}
        self.config_sources = []
        self.schema = self.DEFAULT_SCHEMA

    def load_config(self) -> List[ConfigValidationError]:
        """Load configuration from all sources"""
        # Start with defaults
        self.config = self.schema.defaults.copy()

        # Load from .env file
        load_dotenv()
        env_config = self._load_from_env()
        self.config.update(env_config)
        self.config_sources.append(('.env', list(env_config.keys())))

        # Load from global config file
        global_config_path = os.path.expanduser('~/.swmate.yaml')
        if os.path.exists(global_config_path):
            global_config = self._load_from_yaml(global_config_path)
            self.config.update(global_config)
            self.config_sources.append((global_config_path, list(global_config.keys())))

        # Load from project config file
        project_config_path = 'swmate.yaml'
        if os.path.exists(project_config_path):
            project_config = self._load_from_yaml(project_config_path)
            self.config.update(project_config)
            self.config_sources.append((project_config_path, list(project_config.keys())))

        # Validate configuration
        return self._validate_config()

    def _load_from_env(self) -> Dict[str, Any]:
        """Load configuration from environment variables"""
        config = {}

        # Map environment variables to config keys
        env_mapping = {
            'OPENAI_API_KEY': 'openai_api_key',
            'SWMATE_MODEL': 'default_model',
            'SWMATE_MAX_TOKENS': 'max_tokens',
            'SWMATE_TEMPERATURE': 'temperature',
            'SWMATE_LOG_LEVEL': 'log_level',
            'SWMATE_CACHE_TTL': 'cache_ttl',
            'SWMATE_AUTO_SAVE': 'session_auto_save',
        }

        for env_key, config_key in env_mapping.items():
            if env_key in os.environ:
                value = os.environ[env_key]

                # Convert to appropriate type
                if config_key in self.schema.types:
                    expected_type = self.schema.types[config_key]
                    if expected_type == bool:
                        value = value.lower() in ('true', 'yes', '1')
                    elif expected_type == int:
                        value = int(value)
                    elif expected_type == float:
                        value = float(value)

                config[config_key] = value

        return config

    def _load_from_yaml(self, path: str) -> Dict[str, Any]:
        """Load configuration from YAML file"""
        try:
            with open(path, 'r') as f:
                return yaml.safe_load(f) or {}
        except Exception as e:
            print(f"Error loading config from {path}: {e}")
            return {}

    def _validate_config(self) -> List[ConfigValidationError]:
        """Validate configuration against schema"""
        errors = []

        # Check required keys
        for key in self.schema.required:
            if key not in self.config or self.config[key] is None:
                errors.append(ConfigValidationError(
                    key=key,
                    message=f"Required configuration key '{key}' is missing"
                ))

        # Check types
        for key, expected_type in self.schema.types.items():
            if key in self.config and self.config[key] is not None:
                if not isinstance(self.config[key], expected_type):
                    errors.append(ConfigValidationError(
                        key=key,
                        message=f"Configuration key '{key}' should be of type {expected_type.__name__}"
                    ))

        return errors

    def get(self, key: str, default: Any = None) -> Any:
        """Get configuration value"""
        return self.config.get(key, default)

    def set(self, key: str, value: Any) -> None:
        """Set configuration value (runtime only)"""
        self.config[key] = value

    def get_all(self) -> Dict[str, Any]:
        """Get all configuration values"""
        return self.config.copy()

    def get_sources(self) -> List[tuple]:
        """Get configuration sources"""
        return self.config_sources
