from abc import ABC, abstractmethod

class BaseCoder(ABC):
    """Base class for code editing strategies"""

    def __init__(self, file_manager, debug_manager):
        self.file_manager = file_manager
        self.debug_manager = debug_manager

    @abstractmethod
    def apply_changes(self, file_path, new_content, **kwargs):
        """Apply changes to the file

        Args:
            file_path: Path to the file to modify
            new_content: New content to apply
            **kwargs: Strategy-specific arguments

        Returns:
            dict: Result with success status and details
        """
        pass

    def create_backup(self, file_path):
        """Create a backup of the file before editing"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_path = f"{file_path}.{timestamp}.bak"

        try:
            shutil.copy2(file_path, backup_path)
            self.debug_manager.log(f"Created backup at {backup_path}")
            return backup_path
        except Exception as e:
            self.debug_manager.log(f"Failed to create backup: {str(e)}", level="ERROR")
            return None
