from cli.coders.base_coder import BaseCoder

class WholeFileCoder(BaseCoder):
    """Strategy for replacing entire file contents"""

    def apply_changes(self, file_path, new_content, **kwargs):
        """Replace entire file with new content"""
        # Create backup
        backup_path = self.create_backup(file_path)
        if not backup_path:
            return {
                "success": False,
                "message": "Failed to create backup"
            }

        # Validate content if needed
        if kwargs.get('validate', True):
            validation_result = self._validate_content(file_path, new_content)
            if not validation_result["valid"]:
                return {
                    "success": False,
                    "message": f"Validation failed: {validation_result['reason']}"
                }

        # Write new content
        try:
            with open(file_path, 'w') as f:
                f.write(new_content)

            self.debug_manager.log(f"Successfully replaced content in {file_path}")

            return {
                "success": True,
                "message": "File content replaced",
                "backup_path": backup_path,
                "affected_lines": len(new_content.splitlines())
            }

        except Exception as e:
            self.debug_manager.log(f"Failed to write file: {str(e)}", level="ERROR")
            return {
                "success": False,
                "message": f"Failed to write file: {str(e)}"
            }

    def _validate_content(self, file_path, new_content):
        """Validate new content is appropriate for the file"""
        # Basic validation - can be extended
        if not new_content.strip():
            return {"valid": False, "reason": "Content is empty"}

        # Check file type specific validation
        _, ext = os.path.splitext(file_path.lower())

        if ext == '.c' or ext == '.h':
            # Check for basic C syntax
            if '{' in new_content and '}' not in new_content:
                return {"valid": False, "reason": "Unbalanced braces"}

        elif ext == '.sql':
            # Check for basic SQL syntax
            if 'SELECT' in new_content.upper() and 'FROM' not in new_content.upper():
                return {"valid": False, "reason": "SELECT without FROM"}

        return {"valid": True}
```

